package com.hms.billing;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="tenant_subscriptions") public class TenantSubscription { @Id private UUID tenantId; @Column(nullable=false,length=80) private String planKey; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private SubscriptionStatus status; private LocalDate currentPeriodEnd; private Integer appointmentLimit; private Integer doctorLimit; private Integer userLimit; private Integer branchLimit; private Integer pageLimit; private Integer socialLimit; private Integer notificationLimit; @Column(nullable=false) private OffsetDateTime updatedAt; protected TenantSubscription(){} public TenantSubscription(UUID tenantId,UpdateSubscriptionRequest r){this.tenantId=tenantId;apply(r);} public void apply(UpdateSubscriptionRequest r){planKey=r.planKey();status=r.status();currentPeriodEnd=r.currentPeriodEnd();appointmentLimit=r.appointmentLimit();doctorLimit=r.doctorLimit();userLimit=r.userLimit();branchLimit=r.branchLimit();pageLimit=r.pageLimit();socialLimit=r.socialLimit();notificationLimit=r.notificationLimit();updatedAt=OffsetDateTime.now();} public UUID getTenantId(){return tenantId;} public String getPlanKey(){return planKey;} public SubscriptionStatus getStatus(){return status;} public LocalDate getCurrentPeriodEnd(){return currentPeriodEnd;} public Integer getAppointmentLimit(){return appointmentLimit;} public Integer getDoctorLimit(){return doctorLimit;} public Integer getUserLimit(){return userLimit;} public Integer getBranchLimit(){return branchLimit;} public Integer getPageLimit(){return pageLimit;} public Integer getSocialLimit(){return socialLimit;} public Integer getNotificationLimit(){return notificationLimit;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
